    def test_bulk_download_create(self):
        """Test case for bulk_download_create

        Get advertiser entities in bulk
        """
        body = {"campaign_filter":{"campaign_status":["RUNNING","RUNNING"],"end_time":"1622848072","name":"campaign name","objective_type":["AWARENESS","AWARENESS"],"start_time":"1622848072"},"entity_ids":[null,null],"entity_types":["CAMPAIGN","AD_GROUP"],"output_format":"","updated_since":"1622848072"}
