    def test_bulk_request_get(self):
        """Test case for bulk_request_get

        Download advertiser entities in bulk
        """
        query_string = [('include_details', False)]
        response = self.client.open(
            '/v5/ad_accounts/{ad_account_id}/bulk/{bulk_request_id}'.format(ad_account_id='ad_account_id_example', bulk_request_id='bulk_request_id_example'),
            method='GET',
            query_string=query_string)
        self.assert200(response,
                       'Response body is : ' + response.data.decode('utf-8'))

